using System;
using System.IO;
using System.Linq;
using UnityEngine;
using TMPro;
using CelestialMaker.Core;
using BreakInfinity;
namespace CelestialMaker.EditorTools {
 public static partial class ObservatoryBatch {
  static void DiffEvolution(string name,string before){File.WriteAllText(Path.Combine(Dir,"evolution-"+name+"-before.json"),before);File.WriteAllText(Path.Combine(Dir,"evolution-"+name+"-after.json"),JsonUtility.ToJson(session.Sim.S));}
  static void EvolutionChecks(){
   Check("Development plan remains opt-in with explicit review and stop",()=>{Fixture(false,1,false,1280,720);Set("page","Automation");Call("ShowPc");Require(!Button("Plan Energy").interactable,"Plan unlocked before Prestige");session.Sim.S.resets[0]=1;session.Sim.Meta.historicResets[0]=1;Call("ShowPc");Click("Plan Energy");Click("Cancel");Require(session.Sim.Evolution.developmentPlan=="","Cancel enabled a plan");Click("Plan Energy");Click("Enable development plan");Require(session.Sim.Evolution.developmentPlan=="Energy","Plan callback failed");session.Sim.S.automation.repeatPrestige[0]=true;Click("Stop plan and automatic resets");Require(session.Sim.Evolution.developmentPlan==""&&!session.Sim.S.automation.repeatPrestige.Any(x=>x),"Stop leaves resets enabled");});
   Check("Unity serializes offline cursor ticks and development plan",()=>{Fixture(false,1,false,1920,1080);session.Sim.S.resets[0]=1;session.Sim.ConfigureDevelopmentPlan("Matter");session.Sim.BeginOffline(21600);session.Sim.ProcessOffline(1031);var state=SaveStore.Parse(JsonUtility.ToJson(session.Sim.S));Require(state.evolution.developmentPlan=="Matter"&&state.offlineReport.fixedTicks==1031&&state.offlineRemaining>21580,"Offline state lost on Unity roundtrip");});
   Check("Development review fits large text in both themes",()=>{foreach(bool light in new[]{false,true}){Fixture(true,2,light,1280,720);Set("page","Automation");Call("ShowPc");Click("Plan Time");Settle();Geometry("development confirmation");Require(Button("Enable development plan"),"No confirmation action");Call("ClosePcModal");}});
   Check("Evolution diagnostics and return briefing are actionable",()=>{Fixture(false,1,false,1920,1080);Set("page","Overview");Call("ShowPc");Require(Button("What needs attention?"),"Missing return briefing");Click("What needs attention?");Require(Get<RectTransform>("pcModal").GetComponentsInChildren<TMP_Text>().Any(t=>t.text.Contains("PROGRESS DIAGNOSTICS")),"Missing diagnostic dialog");Geometry("advice dialog");Call("ClosePcModal");});
   Check("Flow navigation changes only the selected economy view",()=>{Fixture(true,1,false,1920,1080);Set("pcWorld",1);Set("page","Analytics");Call("ShowPc");session.Sim.S.offlineReport=new OfflineReport{active=false,dismissed=true};string before=JsonUtility.ToJson(session.Sim.S);Click(GameSession.Content.resources[1]);Require(Get<int>("pcFlowResource")==1,"Resource selection failed");DiffEvolution("flow",before);Require(before==JsonUtility.ToJson(session.Sim.S),"Map mutated economy");});
   Check("Focus preview cancels without mutation",()=>{Fixture(true,1,false,1920,1080);session.Sim.Evolution.focus="Balanced";session.Sim.Evolution.focusReadyAt=0;Set("page","Trees");Call("ShowPc");session.Sim.S.offlineReport=new OfflineReport{active=false,dismissed=true};string before=JsonUtility.ToJson(session.Sim.S);Click("Energy / preview");Click("Cancel");DiffEvolution("focus",before);Require(before==JsonUtility.ToJson(session.Sim.S),"Focus preview changed state");Click("Energy / preview");Click("Apply focus");Require(session.Sim.ActiveFocus=="Energy","Focus not applied");});
   Check("Evolution fields survive Unity serialization",()=>{Fixture(true,1,false,1920,1080);session.Sim.SaveOperations(0,"Fixture");session.Sim.Evolution.cosmosStyle=2;session.Sim.SelectFocus("Matter");var saved=SaveStore.Parse(JsonUtility.ToJson(session.Sim.S));Require(saved.evolution.operations.Count==1&&saved.evolution.cosmosStyle==2&&saved.evolution.focus=="Matter","Evolution data lost");});
   Check("Restore points retain twelve valid isolated snapshots",()=>{Fixture(false,1,false,1280,720);string prior=SaveStore.OverridePath;SaveStore.OverridePath=Path.Combine(ProjectBootstrap.Root,"Logs/ObservatoryEvolution/checkpoint-tests",Guid.NewGuid().ToString("N")+".json");try{for(int i=0;i<14;i++){session.Sim.S.time=i;SaveStore.Checkpoint(session.Sim.S,"test"+i);}var entries=SaveStore.Checkpoints();Require(entries.Length==12&&entries.All(e=>e.state!=null),"Checkpoint retention invalid");Require(entries.Any(e=>e.reason=="test13"),"Checkpoint reason lost");var recovered=SaveStore.ReadCheckpoint(entries[0].file);Require(recovered.time>=2,"Oldest point survived retention");bool rejected=false;try{SaveStore.ReadCheckpoint("../escape.json");}catch(ArgumentException){rejected=true;}Require(rejected,"Restore path escaped folder");Call("CheckpointsPc");Settle();Geometry("checkpoint manager");Call("ClosePcModal");}finally{SaveStore.OverridePath=prior;}});
   Check("Corrupt checkpoints remain visible and cannot load",()=>{Fixture(false,1,false,1280,720);string prior=SaveStore.OverridePath;SaveStore.OverridePath=Path.Combine(ProjectBootstrap.Root,"Logs/ObservatoryEvolution/checkpoint-tests",Guid.NewGuid().ToString("N")+".json");try{Directory.CreateDirectory(SaveStore.CheckpointFolder);File.WriteAllText(Path.Combine(SaveStore.CheckpointFolder,"point-20261011-120000000-broken-aaaaaa.json"),"broken");Require(SaveStore.Checkpoints()[0].state==null,"Corrupt point accepted");Call("CheckpointsPc");Require(!Button("Review restore"),"Corrupt point can be restored");Call("ClosePcModal");}finally{SaveStore.OverridePath=prior;}});
   foreach(bool light in new[]{false,true})foreach(float scale in new[]{1f,2f}){
    foreach(string route in new[]{"Overview","Analytics","Automation","Trees","Prestige","Megastructures"}){var name=route;Check("Evolution responsive "+route+" / "+light+" / "+scale,()=>{Fixture(true,scale,light,1280,720);Set("page",name);Call("ShowPc");Settle();Geometry(name);Call("ExplainViewPc");Settle();Geometry("context guide");Call("ClosePcModal");});}
   }
   Check("Reserve presets capture exact stock and release requires confirmation",()=>{Fixture(true,1,false,1920,1080);Set("page","Automation");session.Sim.S.resources[0]=new BigDouble(1000);Call("ShowPc");Click("Protect 25% of stock");Require(session.Sim.S.reserves[0].Value==250,"Wrong preset amount");session.Sim.S.resources[0]=new BigDouble(2000);Require(session.Sim.S.reserves[0].Value==250,"Reserve followed stock");Click("Review releasing all reserves");Click("Cancel");Require(session.Sim.S.reserves[0].Value==250,"Cancelled release spent reserve");Click("Review releasing all reserves");Click("Release all reserves");Require(session.Sim.S.reserves.All(n=>n.Value==0),"Bulk release incomplete");});
   Check("Short checkpoint filenames remain inspectable",()=>{Fixture(false,1,false,1280,720);string prior=SaveStore.OverridePath;SaveStore.OverridePath=Path.Combine(ProjectBootstrap.Root,"Logs/ObservatoryEvolution/checkpoint-tests",Guid.NewGuid().ToString("N")+".json");try{Directory.CreateDirectory(SaveStore.CheckpointFolder);File.WriteAllText(Path.Combine(SaveStore.CheckpointFolder,"point-x.json"),"broken");Require(SaveStore.Checkpoints()[0].state==null,"Malformed point accepted");}finally{SaveStore.OverridePath=prior;}});
   Check("Living cosmos follows actual chapters and projects",()=>{Fixture(false,1,false,1920,1080);Set("page","Overview");Call("ShowPc");Require(ui.GetComponentInChildren<ObservatoryCosmos>(),"No cosmos renderer");Require(!Button("Genesis").interactable,"Unowned cosmetic unlocked");Fixture(true,1,false,1920,1080);Set("page","Overview");Call("ShowPc");Click("Genesis");Require(session.Sim.Evolution.cosmosStyle==2,"Cosmetic selection not persisted");});
  }
  static void RenderCadence(){
   foreach(bool light in new[]{false,true})foreach(float scale in new[]{1f,2f}){
    Fixture(false,scale,light,scale==1?1920:1280,scale==1?1080:720);session.Sim.S.resets[0]=1;session.Sim.Meta.historicResets[0]=1;
    string key="cadence-"+(light?"dawn":"night")+"-"+(int)(scale*100);Set("page","Automation");Call("ShowPc");Shot(key+"-plan");Click("Plan Energy");Shot(key+"-review");Click("Enable development plan");Shot(key+"-enabled");
    session.Sim.BeginOffline(60);session.Sim.ProcessOffline(1200);Set("pcTick",-1f);Call("UpdatePc");Shot(key+"-catchup");while(session.Sim.S.offlineRemaining>0)session.Sim.ProcessOffline();Call("ShowOfflinePc");Shot(key+"-report");Call("ClosePcModal");
   }
  }
  static void RenderEvolution(){
   foreach(bool light in new[]{false,true})foreach(float scale in new[]{1f,2f}){
    Fixture(true,scale,light,1920,1080);MakeOffline();string key="evolution-"+(light?"dawn":"night")+"-"+(int)(scale*100);
    foreach(string route in new[]{"Overview","Analytics","Automation","Trees","Megastructures"}){Set("page",route);Call("ShowPc");Shot(key+"-"+route.ToLowerInvariant());Shot(key+"-"+route.ToLowerInvariant()+"-bottom",0);}
    Call("ResetPreviewPc",1,false);Shot(key+"-reset");ModalBottom();Shot(key+"-recovery");Call("ClosePcModal");Call("ExplainViewPc");Shot(key+"-guide");Call("ClosePcModal");
   }
   Fixture(true,1,false,1920,1080);Set("page","Trees");Call("ShowPc");Click("Energy / preview");Shot("evolution-focus-comparison");Call("ClosePcModal");Set("page","Automation");Call("ShowPc");Click("Review releasing all reserves");Shot("evolution-reserve-review");Call("ClosePcModal");
   Fixture(false,1,false,1280,720);Set("page","Overview");Call("ShowPc");Shot("evolution-early-overview");Shot("evolution-early-cosmos",0);
   Fixture(true,1,false,1920,1080);session.Sim.SaveOperations(0,"Background");Set("page","Automation");Call("ShowPc");Shot("evolution-operations");
  }
 }
}
